#include "ViewerRuntime.h"
#include "IdDisplayNames.h"
void CaptureV0412Ui(const fs::path&,HWND);
namespace {
const std::wstring U=L"usr_12345678-1234-1234-1234-123456789abc",W=L"wrld_12345678-1234-1234-1234-123456789abc",B=L"wrld_22345678-1234-1234-1234-123456789abc",G=L"grp_12345678-1234-1234-1234-123456789abc";
void Bytes(const fs::path& p,const std::string& text){std::ofstream f(p,std::ios::binary|std::ios::trunc);f.write(text.data(),text.size());if(!f)throw std::runtime_error("fixture write failed");}
}
void RunIdNameTests(const fs::path& directory,std::ostream& report){
    auto check=[&](bool v,const char* text){report<<(v?"PASS: ":"FAIL: ")<<"v0.5.8 "<<text<<std::endl;if(!v)throw std::runtime_error(text);};
    auto rejects=[&](auto action){try{action();return false;}catch(...){return true;}};
    IdNameTable names{{U,L"人物 ｶﾅ 中文 한국어 📷"},{W,L"ワールド"},{G,L"グループ"}};auto json=SerializeIdNames(names);check(ParseIdNames(json).names==names&&ParseIdNames("\xef\xbb\xbf"+json).names==names,"UTF-8 Unicode emoji and optional BOM roundtrip");
    check(DisplayIdUrl(U)==L"https://vrchat.com/home/user/"+U&&DisplayIdUrl(W)==L"https://vrchat.com/home/world/"+W&&DisplayIdUrl(G)==L"https://vrchat.com/home/group/"+G&&DisplayIdUrl(L"../bad").empty(),"three validated IDs generate browser URLs only");
    auto uppercase=U;uppercase.back()=L'C';check(CanonicalDisplayId(uppercase)==U&&ValidateDisplayName(L"  Name 内部  空白  ")==L"Name 内部  空白","ID normalization and name whitespace rules");
    for(auto text:{std::string("\xff"),std::string("\xff\xfe{\0",4),std::string("{}"),std::string(9*1024*1024,'x')})check(rejects([&]{ParseIdNames(text);}),"invalid encoding format or oversized import rejected");
    auto changed=json;changed.replace(changed.find("\"version\":1"),11,"\"version\":2");check(rejects([&]{ParseIdNames(changed);}),"unknown format version rejected");
    auto raw=[&](const std::string& entries){return std::string("{\"format\":\"KuniVRCPhotEditor.IdDisplayNames\",\"version\":1,\"entries\":")+entries+"}";};auto sid=winrt::to_string(U);
    auto escaped=raw("[{\"type\":\"person\",\"id\":\""+sid+"\",\"displayName\":\"\\u4eba\\u7269 \\ud83d\\udcf7\"}]");check(ParseIdNames(escaped).names.at(U)==L"人物 📷","escaped Unicode and surrogate pair decoded");
    for(auto name:{"\\ud800","\\udc00","a\\u0000b","a\\nb"})check(rejects([&]{ParseIdNames(raw("[{\"type\":\"person\",\"id\":\""+sid+"\",\"displayName\":\""+name+"\"}]"));}),"unpaired Unicode or control character rejected");
    check(rejects([&]{ParseIdNames(raw("[{\"type\":\"group\",\"id\":\""+sid+"\",\"displayName\":\"N\"}]"));}),"ID type mismatch rejected");
    auto incomplete=ParseIdNames(raw("[{\"displayName\":\"Name only\"},{\"type\":\"person\",\"id\":\""+sid+"\",\"displayName\":\"\"}]"));check(incomplete.names.empty()&&incomplete.skipped==2,"name-only and empty-name entries skipped without reverse lookup");
    IdNameTable base{{U,L"Existing"}};auto merged=MergeIdNames(base,{names,2});check(base.at(U)==L"Existing"&&base.at(W)==names.at(W)&&merged.added==2&&merged.kept==1&&merged.skipped==2,"import preserves nonempty existing names and missing entries");
    auto duplicate=raw("[{\"type\":\"person\",\"id\":\""+sid+"\",\"displayName\":\"A\"},{\"type\":\"person\",\"id\":\""+sid+"\",\"displayName\":\"B\"}]");check(rejects([&]{ParseIdNames(duplicate);}),"conflicting duplicates in one import rejected");
    auto root=directory/L"id-names-unit";fs::create_directories(root);auto path=root/L"IdDisplayNames.json";fs::remove(path);IdNameStore store;store.Load(path);check(store.Snapshot().empty()&&!fs::exists(path),"empty store does not create a file");store.Save(names);check(ParseIdNames(ReadIdNamesFile(path)).names==names,"atomic store save persists aliases");
    IdNameStore reopened;reopened.Load(path);check(reopened.Snapshot()==names,"aliases survive restart independently of MDB");auto external=SerializeIdNames({{W,L"External"}});Bytes(path,external);check(rejects([&]{store.Save({});})&&ReadIdNamesFile(path)==external,"external edits cannot be overwritten by a stale dialog");
    Bytes(path,"broken original");store.Load(path);check(!store.Error().empty()&&store.Snapshot().empty()&&rejects([&]{store.Save(names);})&&ReadIdNamesFile(path)=="broken original","corrupt table is preserved and cannot be replaced with empty data");
    Bytes(path,json);store.Load(path);store.Save({{W,L"One"},{G,L"One"}});check(store.Snapshot().size()==2,"identical names keep distinct ID keys");auto lockPath=path;lockPath+=L".lock";Bytes(lockPath,"foreign lock data");auto beforeLock=ReadIdNamesFile(path);check(rejects([&]{store.Save(names);})&&ReadIdNamesFile(path)==beforeLock&&ReadIdNamesFile(lockPath)=="foreign lock data","unknown lock file prevents save without changing either file");fs::remove(lockPath);
    auto output=root/L"export.json";ExportIdNames(output,names);check(ReadIdNamesFile(output)==json,"export roundtrip is deterministic UTF-8 without BOM");auto invalid=names;invalid[U]=L"a\nb";check(rejects([&]{ExportIdNames(output,invalid);})&&ReadIdNamesFile(output)==json,"failed export leaves existing file unchanged");auto folder=root/L"directory-target";fs::create_directories(folder);check(rejects([&]{ExportIdNames(folder,names);})&&fs::is_directory(folder),"replacement failure preserves destination");
}
void RunIdNameUiTests(const fs::path& directory,std::ostream& report){
    auto check=[&](bool v,const char* text){report<<(v?"PASS: ":"FAIL: ")<<"v0.5.8 "<<text<<std::endl;if(!v)throw std::runtime_error(text);};
    auto wait=[&](auto done){auto until=GetTickCount64()+30000;while(!done()){if(GetTickCount64()>until)throw std::runtime_error("alias UI async timeout");MSG m{};while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}Sleep(10);}};
    auto table=app.settings.parent_path()/L"IdDisplayNames.json";fs::remove(table);app.mdbEnabled=false;ConfigureMdb();bool shown=false;ShowIdNamesDialog(app.window,{{[&](HWND){shown=true;}}});check(!shown&&!fs::exists(table),"MDB OFF disables name editing");
    ShowMdbDialog([&](HWND h){check(!IsWindowEnabled(GetDlgItem(h,2304)),"MDB OFF disables settings entry");});
    auto root=directory/L"id-names-ui";fs::create_directories(root);auto source=directory/L"sample-日本語.png";auto original=MetadataFingerprint(source.wstring());
    for(int i=0;i<3;++i){MetadataEdit edit;for(auto& action:edit.actions)action=EditAction::Set;edit.values={L"2026-10-18T12:00:00+09:00",L"Photographer",L"Original World Name",i==0?W:i==1?B:L"",L"Name without ID",L"Test"};if(i==2)edit.actions[3]=EditAction::Remove;auto file=root/(std::to_wstring(i)+L".png");fs::remove(file);SaveMetadataCopy(source.wstring(),file.wstring(),MetadataFingerprint(source.wstring()),edit);}
    app.mdbEnabled=true;app.categoryMode=0;ConfigureMdb();app.mdb.WaitIdle();app.appliedQuery.clear();OpenFolder(root.wstring(),true);wait([]{return !app.folderPending&&ThumbnailsReady();});app.mdb.WaitIdle();RequestCategory(4);wait([]{return !app.searching&&!app.sorting&&ThumbnailsReady();});
    check(std::any_of(app.mdbRows.begin(),app.mdbRows.end(),[](auto& r){return r.key==W&&r.label==W;})&&std::any_of(app.mdbRows.begin(),app.mdbRows.end(),[](auto& r){return r.label==L"情報なし";}),"unregistered world shows ID and name-only photo stays unclassified");
    ListView_SetItemState(app.list,0,LVIS_SELECTED|LVIS_FOCUSED,LVIS_SELECTED|LVIS_FOCUSED);FlushSelectionUpdate();wait([]{return app.metadataReady;});auto selected=SelectedFiles();auto focus=app.selected;
    auto importFile=root/L"import.json",exportFile=root/L"export.json",badImport=root/L"invalid.json";Bytes(badImport,"broken import");std::wstring importChoice=importFile.wstring(),exportChoice=exportFile.wstring();ExportIdNames(importFile,{{W,L"Import World"},{U,L"人物 📷"},{G,L"Unused group"}});
    auto row=[&](HWND h,const std::wstring& id){auto list=GetDlgItem(h,2400);for(int i=0;i<ListView_GetItemCount(list);++i){wchar_t value[128]{};ListView_GetItemText(list,i,1,value,128);if(value==id)return i;}return -1;};
    auto edit=[&](HWND h,const std::wstring& id,const wchar_t* name){auto list=GetDlgItem(h,2400);int index=row(h,id);check(index>=0,"expected ID is present in the three-column table");auto control=ListView_EditLabel(list,index);check(control!=nullptr,"display name cell can be edited");SetWindowTextW(control,name);MSG key{control,WM_KEYDOWN,VK_RETURN,0};if(!IsDialogMessageW(h,&key)){TranslateMessage(&key);DispatchMessageW(&key);}check(IsWindow(h),"Enter in a cell does not save or close the dialog");wchar_t value[1100]{};ListView_GetItemText(list,index,0,value,1100);check(value==std::wstring(name),"label edit updates the visible row");};
    std::vector<std::wstring> urls;bool personal=false;IdNameUiHooks hooks;hooks.importPath=[&]{return importChoice;};hooks.exportPath=[&]{return exportChoice;};hooks.confirmExport=[&](size_t count,bool contains){personal=contains;return count==3;};hooks.openUrl=[&](auto& url){urls.push_back(url);};hooks.inspect=[&](HWND h){auto list=GetDlgItem(h,2400);check(Header_GetItemCount(ListView_GetHeader(list))==3&&GetDlgItem(h,IDOK)&&GetDlgItem(h,IDCANCEL)&&GetDlgItem(h,2401)&&GetDlgItem(h,2402),"three columns and four buttons are available");int index=row(h,W);wchar_t empty[16]{};ListView_GetItemText(list,index,0,empty,16);check(!*empty,"metadata name is not copied into the editable display name");NMITEMACTIVATE click{};click.hdr={list,2400,NM_CLICK};click.iItem=index;click.iSubItem=2;SendMessageW(h,WM_NOTIFY,2400,reinterpret_cast<LPARAM>(&click));check(urls==std::vector<std::wstring>{DisplayIdUrl(W)},"shortcut opens only the validated ID page via browser hook");SendMessageW(h,WM_COMMAND,2401,0);edit(h,W,L"未保存の世界 📷");SendMessageW(h,WM_COMMAND,2401,0);wchar_t kept[128]{};ListView_GetItemText(list,row(h,W),0,kept,128);check(std::wstring(kept)==L"未保存の世界 📷","re-import keeps an existing edited name");importChoice=badImport.wstring();SendMessageW(h,WM_COMMAND,2401,0);importChoice=importFile.wstring();ListView_GetItemText(list,row(h,W),0,kept,128);check(std::wstring(kept)==L"未保存の世界 📷","invalid import cannot partially replace the editing table");for(auto& id:{U,G}){click.iItem=row(h,id);SendMessageW(h,WM_NOTIFY,2400,reinterpret_cast<LPARAM>(&click));}check(urls==std::vector<std::wstring>{DisplayIdUrl(W),DisplayIdUrl(U),DisplayIdUrl(G)},"all shortcut types use the correct profile pages");auto cancelled=ListView_EditLabel(list,row(h,G));SetWindowTextW(cancelled,L"Discarded edit");MSG escape{cancelled,WM_KEYDOWN,VK_ESCAPE,0};if(!IsDialogMessageW(h,&escape))DispatchMessageW(&escape);wchar_t groupName[128]{};ListView_GetItemText(list,row(h,G),0,groupName,128);check(IsWindow(h)&&std::wstring(groupName)==L"Unused group","Escape cancels only the current cell edit");exportChoice=table.wstring();SendMessageW(h,WM_COMMAND,2402,0);check(!fs::exists(table),"Export cannot bypass Save by targeting the internal table file");exportChoice=exportFile.wstring();SendMessageW(h,WM_COMMAND,2402,0);check(personal&&ParseIdNames(ReadIdNamesFile(exportFile)).names.at(W)==L"未保存の世界 📷"&&!fs::exists(table),"export includes unsaved edits and warns about person IDs without saving locally");SendMessageW(h,WM_COMMAND,IDCANCEL,0);};ShowIdNamesDialog(app.window,hooks);check(app.idNames.Snapshot().empty()&&!fs::exists(table)&&fs::exists(exportFile),"cancel discards imported edits but preserves the exported file");
    hooks.inspect=[&](HWND h){SendMessageW(h,WM_COMMAND,2401,0);edit(h,W,L"同じ表示名 📷");auto list=GetDlgItem(h,2400);auto control=ListView_EditLabel(list,row(h,B));SetWindowTextW(control,L"同じ表示名 📷");SendMessageW(h,WM_COMMAND,IDOK,0);};ShowIdNamesDialog(app.window,hooks);check(app.idNames.Snapshot().at(W)==L"同じ表示名 📷"&&app.idNames.Snapshot().at(B)==L"同じ表示名 📷"&&SelectedFiles()==selected&&app.selected==focus,"save updates headers while preserving distinct IDs and selected photo");
    check(std::count_if(app.mdbRows.begin(),app.mdbRows.end(),[](auto& r){return r.label==L"同じ表示名 📷";})==2&&app.summary.values[5]==L"Original World Name"&&MetadataFingerprint(source.wstring())==original,"manual names affect only category headers, not original metadata");std::set<std::wstring> headerIds;for(int n=0;n<ListView_GetGroupCount(app.list);++n){LVGROUP group{sizeof(group)};group.mask=LVGF_GROUPID;if(ListView_GetGroupInfoByIndex(app.list,n,&group)){RECT r{};if(ListView_GetGroupRect(app.list,group.iGroupId,LVGGR_HEADER,&r)){auto id=MdbHeaderIdAt({r.left+4,(r.top+r.bottom)/2});if(!id.empty())headerIds.insert(id);}}}check(headerIds==std::set<std::wstring>{W,B},"same-name group headers retain distinct IDs for tooltip lookup");auto subject=directory/L"id-names-subject.png";MetadataEdit subjectEdit;subjectEdit.actions[5]=EditAction::Set;subjectEdit.values[5]=L"【グループID】"+G;stage3::Record capture;capture.memberStatus=L"reconstructed";capture.members={{L"Original User",U}};subjectEdit.createCaptureRecord=true;subjectEdit.stage3Xml=stage3::RecordXml(capture,true);fs::remove(subject);SaveMetadataCopy(source.wstring(),subject.wstring(),MetadataFingerprint(source.wstring()),subjectEdit);for(int mode:{2,5}){Job job{13,app.generation};job.searchGeneration=app.searchGeneration;job.categoryMode=mode;job.files={subject.wstring()};Result result;RunCategory(job,result);auto id=mode==2?U:G;check(result.mdbRows.size()==1&&result.mdbRows[0].key==id&&result.mdbRows[0].label==app.idNames.Snapshot().at(id),"person and group ID categories use the independent name table");}
    for(auto& r:app.mdbRows)if(!CanonicalDisplayId(r.key).empty())r.label=L"stale result";SetupMdbGroups();check(std::none_of(app.mdbRows.begin(),app.mdbRows.end(),[](auto& r){return r.label==L"stale result";}),"committed category results resolve the latest name table");
    for(bool dark:{false,true}){app.darkTheme=dark;ApplyTheme();hooks.inspect=[&](HWND h){check(row(h,G)>=0&&row(h,U)>=0,"imported IDs not in the current MDB remain editable");CaptureV0412Ui(directory/(dark?L"id-names-dark.png":L"id-names-light.png"),h);SetWindowPos(h,nullptr,0,0,680,340,SWP_NOMOVE|SWP_NOZORDER);RECT list{},button{};GetWindowRect(GetDlgItem(h,2400),&list);GetWindowRect(GetDlgItem(h,IDOK),&button);check(list.bottom<button.top,"resizing keeps the table above its buttons");SendMessageW(h,WM_COMMAND,IDCANCEL,0);};ShowIdNamesDialog(app.window,hooks);}
    app.darkTheme=false;ApplyTheme();hooks.inspect=[&](HWND h){edit(h,W,L"");SendMessageW(h,WM_COMMAND,IDOK,0);};ShowIdNamesDialog(app.window,hooks);check(!app.idNames.Snapshot().count(W)&&std::any_of(app.mdbRows.begin(),app.mdbRows.end(),[](auto& r){return r.key==W&&r.label==W;}),"clearing a name restores ID rather than metadata-derived name");
    auto stored=ReadIdNamesFile(table);app.mdbEnabled=false;app.categoryMode=0;ConfigureMdb();app.mdb.WaitIdle();check(fs::exists(table)&&ReadIdNamesFile(table)==stored&&!fs::exists(app.settings.parent_path()/L"MetadataDB"/L"mdb.sqlite"),"MDB deletion preserves the independent name table");app.mdbEnabled=true;ConfigureMdb();check(app.idNames.Snapshot().at(B)==L"同じ表示名 📷","MDB re-enable restores the name table");app.mdbEnabled=false;ConfigureMdb();app.mdb.WaitIdle();
}
int IdNamesTest(){auto directory=app.settings.parent_path();std::ofstream report(directory/L"id-names-result.txt");try{RunIdNameTests(directory,report);RunIdNameUiTests(directory,report);report<<"ALL PASSED\n";return 0;}catch(const std::exception& e){report<<"FAIL: "<<e.what()<<std::endl;return 1;}}
